# -*- coding: utf-8 -*-
# 5-matematik-14 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DOĞAL SAYILARLA ÇOK ADIMLI PROBLEM ÇÖZME SÜRECİ (MAT.5.1.2)</text>\n  <rect x="20" y="52" width="155" height="184" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="97" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Problemi Anlama</text>\n  <text x="97" y="106" text-anchor="middle" font-size="11" fill="#1e3a8a">• Verilen nicelikleri</text>\n  <text x="97" y="124" text-anchor="middle" font-size="11" fill="#1e3a8a">ve birimleri belirle</text>\n  <text x="97" y="148" text-anchor="middle" font-size="11" fill="#1e3a8a">• İstenen hedefi ve</text>\n  <text x="97" y="166" text-anchor="middle" font-size="11" fill="#1e3a8a">koşulları netleştir</text>\n  <text x="97" y="206" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">Tablo veya şema çiz</text>\n\n  <rect x="190" y="52" width="155" height="184" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="267" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. Plan Yapma</text>\n  <text x="267" y="106" text-anchor="middle" font-size="11" fill="#14532d">• İşlem sırasını kur</text>\n  <text x="267" y="124" text-anchor="middle" font-size="11" fill="#14532d">• Kat kutusu, ters</text>\n  <text x="267" y="142" text-anchor="middle" font-size="11" fill="#14532d">işlem veya kalan</text>\n  <text x="267" y="160" text-anchor="middle" font-size="11" fill="#14532d">yorumunu seç</text>\n  <text x="267" y="206" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Önce tahmin yürüt</text>\n\n  <rect x="360" y="52" width="155" height="184" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="437" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">3. Planı Uygulama</text>\n  <text x="437" y="106" text-anchor="middle" font-size="11" fill="#78350f">• Adım adım dört</text>\n  <text x="437" y="124" text-anchor="middle" font-size="11" fill="#78350f">işlemi gerçekleştir</text>\n  <text x="437" y="148" text-anchor="middle" font-size="11" fill="#78350f">• Ara sonuçların</text>\n  <text x="437" y="166" text-anchor="middle" font-size="11" fill="#78350f">birimini yaz</text>\n  <text x="437" y="206" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">Bölünen = B x B + K</text>\n\n  <rect x="530" y="52" width="150" height="184" rx="8" fill="#f5f3ff" stroke="#7c3aed" stroke-width="1.5"/>\n  <text x="605" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#6d28d9">4. Kontrol ve Genelleme</text>\n  <text x="605" y="106" text-anchor="middle" font-size="11" fill="#4c1d95">• Sonucu tahminle</text>\n  <text x="605" y="124" text-anchor="middle" font-size="11" fill="#4c1d95">ve ters işlemle sına</text>\n  <text x="605" y="148" text-anchor="middle" font-size="11" fill="#4c1d95">• Stratejiyi benzer</text>\n  <text x="605" y="166" text-anchor="middle" font-size="11" fill="#4c1d95">durumlara uyarla</text>\n  <text x="605" y="206" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#5b21b6">Mantıksal doğrulama</text>\n</svg>', '1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DOĞAL SAYILARLA ÇOK ADIMLI PROBLEM ÇÖZME SÜRECİ (MAT.5.1.2)</text>\n  <rect x="20" y="52" width="155" height="184" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="97" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Problemi Anlama</text>\n  <text x="97" y="106" text-anchor="middle" font-size="11" fill="#1e3a8a">• Verilen nicelikleri</text>\n  <text x="97" y="124" text-anchor="middle" font-size="11" fill="#1e3a8a">ve birimleri belirle</text>\n  <text x="97" y="148" text-anchor="middle" font-size="11" fill="#1e3a8a">• İstenen hedefi ve</text>\n  <text x="97" y="166" text-anchor="middle" font-size="11" fill="#1e3a8a">koşulları netleştir</text>\n  <text x="97" y="206" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">Tablo veya şema çiz</text>\n\n  <rect x="190" y="52" width="155" height="184" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="267" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. Plan Yapma</text>\n  <text x="267" y="106" text-anchor="middle" font-size="11" fill="#14532d">• İşlem sırasını kur</text>\n  <text x="267" y="124" text-anchor="middle" font-size="11" fill="#14532d">• Kat kutusu, ters</text>\n  <text x="267" y="142" text-anchor="middle" font-size="11" fill="#14532d">işlem veya kalan</text>\n  <text x="267" y="160" text-anchor="middle" font-size="11" fill="#14532d">yorumunu seç</text>\n  <text x="267" y="206" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Önce tahmin yürüt</text>\n\n  <rect x="360" y="52" width="155" height="184" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="437" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">3. Planı Uygulama</text>\n  <text x="437" y="106" text-anchor="middle" font-size="11" fill="#78350f">• Adım adım dört</text>\n  <text x="437" y="124" text-anchor="middle" font-size="11" fill="#78350f">işlemi gerçekleştir</text>\n  <text x="437" y="148" text-anchor="middle" font-size="11" fill="#78350f">• Ara sonuçların</text>\n  <text x="437" y="166" text-anchor="middle" font-size="11" fill="#78350f">birimini yaz</text>\n  <text x="437" y="206" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">Bölünen = B x B + K</text>\n\n  <rect x="530" y="52" width="150" height="184" rx="8" fill="#f5f3ff" stroke="#7c3aed" stroke-width="1.5"/>\n  <text x="605" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#6d28d9">4. Kontrol ve Genelleme</text>\n  <text x="605" y="106" text-anchor="middle" font-size="11" fill="#4c1d95">• Sonucu tahminle</text>\n  <text x="605" y="124" text-anchor="middle" font-size="11" fill="#4c1d95">ve ters işlemle sına</text>\n  <text x="605" y="148" text-anchor="middle" font-size="11" fill="#4c1d95">• Stratejiyi benzer</text>\n  <text x="605" y="166" text-anchor="middle" font-size="11" fill="#4c1d95">durumlara uyarla</text>\n  <text x="605" y="206" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#5b21b6">Mantıksal doğrulama</text>\n</svg>', 'b2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KAT MODELİ VE KALANLI BÖLME STRATEJİLERİ</text>\n  <rect x="20" y="46" width="320" height="194" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="180" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kat ve Fazlalık Modeli (Kutu Şeması)</text>\n  <text x="60" y="102" font-size="11.5" font-weight="bold" fill="#1e3a8a">1. Sayı:</text>\n  <rect x="115" y="88" width="45" height="22" fill="#93c5fd" stroke="#1d4ed8"/>\n  <text x="60" y="134" font-size="11.5" font-weight="bold" fill="#1e3a8a">2. Sayı:</text>\n  <rect x="115" y="120" width="45" height="22" fill="#93c5fd" stroke="#1d4ed8"/>\n  <rect x="165" y="120" width="45" height="22" fill="#93c5fd" stroke="#1d4ed8"/>\n  <rect x="215" y="120" width="45" height="22" fill="#93c5fd" stroke="#1d4ed8"/>\n  <text x="278" y="136" font-size="12" font-weight="bold" fill="#1d4ed8">+ 15</text>\n  <text x="180" y="170" text-anchor="middle" font-size="11.5" fill="#1e3a8a">Toplam = 4 kat + 15 = 195 ise:</text>\n  <text x="180" y="192" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1) 195 - 15 = 180   2) 180 / 4 = 45 (1 kat)</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" fill="#334155">Önce fazlalık çıkarılır, sonra toplam kat sayısına bölünür.</text>\n\n  <rect x="360" y="46" width="320" height="194" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="520" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Kalanlı Bölmede Gerçek Yaşam Yorumu</text>\n  <text x="520" y="100" text-anchor="middle" font-size="11.5" fill="#78350f">Örnek: 130 yolcu, 12 kişilik minibüslere binecek:</text>\n  <text x="520" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">130 = (12 x 10) + 10 (Bölüm: 10, Kalan: 10)</text>\n  <text x="520" y="154" text-anchor="middle" font-size="11.5" fill="#78350f">• «En az kaç minibüs gerekir?» — 10 + 1 = 11 araç</text>\n  <text x="520" y="178" text-anchor="middle" font-size="11.5" fill="#78350f">• «Kaç minibüs tamamen dolar?» — 10 araç</text>\n  <text x="520" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Sorunun bağlamına göre bölüm veya (bölüm + 1) alınır.</text>\n</svg>', '2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KAT MODELİ VE KALANLI BÖLME STRATEJİLERİ</text>\n  <rect x="20" y="46" width="320" height="194" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="180" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kat ve Fazlalık Modeli (Kutu Şeması)</text>\n  <text x="60" y="102" font-size="11.5" font-weight="bold" fill="#1e3a8a">1. Sayı:</text>\n  <rect x="115" y="88" width="45" height="22" fill="#93c5fd" stroke="#1d4ed8"/>\n  <text x="60" y="134" font-size="11.5" font-weight="bold" fill="#1e3a8a">2. Sayı:</text>\n  <rect x="115" y="120" width="45" height="22" fill="#93c5fd" stroke="#1d4ed8"/>\n  <rect x="165" y="120" width="45" height="22" fill="#93c5fd" stroke="#1d4ed8"/>\n  <rect x="215" y="120" width="45" height="22" fill="#93c5fd" stroke="#1d4ed8"/>\n  <text x="278" y="136" font-size="12" font-weight="bold" fill="#1d4ed8">+ 15</text>\n  <text x="180" y="170" text-anchor="middle" font-size="11.5" fill="#1e3a8a">Toplam = 4 kat + 15 = 195 ise:</text>\n  <text x="180" y="192" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1) 195 - 15 = 180   2) 180 / 4 = 45 (1 kat)</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" fill="#334155">Önce fazlalık çıkarılır, sonra toplam kat sayısına bölünür.</text>\n\n  <rect x="360" y="46" width="320" height="194" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="520" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Kalanlı Bölmede Gerçek Yaşam Yorumu</text>\n  <text x="520" y="100" text-anchor="middle" font-size="11.5" fill="#78350f">Örnek: 130 yolcu, 12 kişilik minibüslere binecek:</text>\n  <text x="520" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">130 = (12 x 10) + 10 (Bölüm: 10, Kalan: 10)</text>\n  <text x="520" y="154" text-anchor="middle" font-size="11.5" fill="#78350f">• «En az kaç minibüs gerekir?» — 10 + 1 = 11 araç</text>\n  <text x="520" y="178" text-anchor="middle" font-size="11.5" fill="#78350f">• «Kaç minibüs tamamen dolar?» — 10 araç</text>\n  <text x="520" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Sorunun bağlamına göre bölüm veya (bölüm + 1) alınır.</text>\n</svg>', 'b3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÇEVRESİ VERİLEN DİKDÖRTGENİN KENAR UZUNLUKLARINI YORUMLAMA</text>\n  <rect x="25" y="48" width="300" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="175" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Yarı Çevre Kuralı (MAT.5.4.1)</text>\n  <rect x="75" y="92" width="200" height="75" fill="#bbf7d0" stroke="#15803d" stroke-width="2.5"/>\n  <text x="175" y="86" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">Uzun Kenar (b)</text>\n  <text x="50" y="134" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">a</text>\n  <text x="175" y="135" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Çevre = 2 x (a + b)</text>\n  <text x="175" y="192" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Yarı Çevre: a + b = Çevre / 2</text>\n  <text x="175" y="216" text-anchor="middle" font-size="11" fill="#334155">Çevre her zaman çift bir doğal sayıdır.</text>\n\n  <rect x="345" y="48" width="330" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="510" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Örnek: Çevre = 20 cm ise a + b = 10 cm</text>\n  <text x="510" y="98" text-anchor="middle" font-size="11.5" fill="#155e75">Doğal sayı kenar çiftleri (a, b):</text>\n  <text x="510" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f766e">• 1 cm ve 9 cm  (Toplam = 10, Çevre = 20)</text>\n  <text x="510" y="144" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f766e">• 2 cm ve 8 cm  (Toplam = 10, Çevre = 20)</text>\n  <text x="510" y="166" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f766e">• 3 cm ve 7 cm  (Toplam = 10, Çevre = 20)</text>\n  <text x="510" y="188" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f766e">• 4 cm ve 6 cm  ·  5 cm ve 5 cm (Kare özel hâli)</text>\n  <text x="510" y="216" text-anchor="middle" font-size="11" fill="#164e63">Toplam 5 farklı dikdörtgen oluşturulabilir.</text>\n</svg>', '3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÇEVRESİ VERİLEN DİKDÖRTGENİN KENAR UZUNLUKLARINI YORUMLAMA</text>\n  <rect x="25" y="48" width="300" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="175" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Yarı Çevre Kuralı (MAT.5.4.1)</text>\n  <rect x="75" y="92" width="200" height="75" fill="#bbf7d0" stroke="#15803d" stroke-width="2.5"/>\n  <text x="175" y="86" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">Uzun Kenar (b)</text>\n  <text x="50" y="134" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">a</text>\n  <text x="175" y="135" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Çevre = 2 x (a + b)</text>\n  <text x="175" y="192" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Yarı Çevre: a + b = Çevre / 2</text>\n  <text x="175" y="216" text-anchor="middle" font-size="11" fill="#334155">Çevre her zaman çift bir doğal sayıdır.</text>\n\n  <rect x="345" y="48" width="330" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="510" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Örnek: Çevre = 20 cm ise a + b = 10 cm</text>\n  <text x="510" y="98" text-anchor="middle" font-size="11.5" fill="#155e75">Doğal sayı kenar çiftleri (a, b):</text>\n  <text x="510" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f766e">• 1 cm ve 9 cm  (Toplam = 10, Çevre = 20)</text>\n  <text x="510" y="144" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f766e">• 2 cm ve 8 cm  (Toplam = 10, Çevre = 20)</text>\n  <text x="510" y="166" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f766e">• 3 cm ve 7 cm  (Toplam = 10, Çevre = 20)</text>\n  <text x="510" y="188" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f766e">• 4 cm ve 6 cm  ·  5 cm ve 5 cm (Kare özel hâli)</text>\n  <text x="510" y="216" text-anchor="middle" font-size="11" fill="#164e63">Toplam 5 farklı dikdörtgen oluşturulabilir.</text>\n</svg>', 'b4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AYNI ÇEVREYE SAHİP DİKDÖRTGENLERİN ALAN KARŞILAŞTIRMASI</text>\n  <rect x="20" y="50" width="205" height="186" rx="8" fill="#fff1f2" stroke="#e11d48" stroke-width="1.5"/>\n  <text x="122" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be123c">1. Kenarlar Uzak (1 x 9)</text>\n  <rect x="42" y="102" width="160" height="18" fill="#fecdd3" stroke="#e11d48" stroke-width="2"/>\n  <text x="122" y="148" text-anchor="middle" font-size="12" fill="#881337">Çevre = 2 x (1 + 9) = 20 br</text>\n  <text x="122" y="174" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Alan = 1 x 9 = 9 br kare</text>\n  <text x="122" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">EN KÜÇÜK ALAN</text>\n\n  <rect x="247" y="50" width="205" height="186" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="350" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">2. Orta Durum (3 x 7)</text>\n  <rect x="285" y="92" width="130" height="42" fill="#fde68a" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="158" text-anchor="middle" font-size="12" fill="#78350f">Çevre = 2 x (3 + 7) = 20 br</text>\n  <text x="350" y="182" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Alan = 3 x 7 = 21 br kare</text>\n  <text x="350" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">ARA ALAN DEĞERİ</text>\n\n  <rect x="475" y="50" width="205" height="186" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="577" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">3. Kenarlar Yakın (5 x 5)</text>\n  <rect x="537" y="84" width="80" height="58" fill="#bbf7d0" stroke="#16a34a" stroke-width="2"/>\n  <text x="577" y="160" text-anchor="middle" font-size="12" fill="#14532d">Çevre = 2 x (5 + 5) = 20 br</text>\n  <text x="577" y="184" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Alan = 5 x 5 = 25 br kare</text>\n  <text x="577" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">EN BÜYÜK ALAN</text>\n</svg>', '4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AYNI ÇEVREYE SAHİP DİKDÖRTGENLERİN ALAN KARŞILAŞTIRMASI</text>\n  <rect x="20" y="50" width="205" height="186" rx="8" fill="#fff1f2" stroke="#e11d48" stroke-width="1.5"/>\n  <text x="122" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be123c">1. Kenarlar Uzak (1 x 9)</text>\n  <rect x="42" y="102" width="160" height="18" fill="#fecdd3" stroke="#e11d48" stroke-width="2"/>\n  <text x="122" y="148" text-anchor="middle" font-size="12" fill="#881337">Çevre = 2 x (1 + 9) = 20 br</text>\n  <text x="122" y="174" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Alan = 1 x 9 = 9 br kare</text>\n  <text x="122" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">EN KÜÇÜK ALAN</text>\n\n  <rect x="247" y="50" width="205" height="186" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="350" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">2. Orta Durum (3 x 7)</text>\n  <rect x="285" y="92" width="130" height="42" fill="#fde68a" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="158" text-anchor="middle" font-size="12" fill="#78350f">Çevre = 2 x (3 + 7) = 20 br</text>\n  <text x="350" y="182" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Alan = 3 x 7 = 21 br kare</text>\n  <text x="350" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">ARA ALAN DEĞERİ</text>\n\n  <rect x="475" y="50" width="205" height="186" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="577" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">3. Kenarlar Yakın (5 x 5)</text>\n  <rect x="537" y="84" width="80" height="58" fill="#bbf7d0" stroke="#16a34a" stroke-width="2"/>\n  <text x="577" y="160" text-anchor="middle" font-size="12" fill="#14532d">Çevre = 2 x (5 + 5) = 20 br</text>\n  <text x="577" y="184" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Alan = 5 x 5 = 25 br kare</text>\n  <text x="577" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">EN BÜYÜK ALAN</text>\n</svg>', 'b5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AYNI ALANA SAHİP DİKDÖRTGENLERDE ÇEVRE ANALİZİ (ALAN = 24 BR KARE)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Çarpan Çiftleriyle Kenar Bulma</text>\n  <text x="182" y="100" text-anchor="middle" font-size="12" fill="#1e3a8a">Alan = a x b = 24 birimkare ise:</text>\n  <text x="182" y="126" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">• 1 x 24 = 24  —  Çevre = 2 x (1 + 24) = 50 br</text>\n  <text x="182" y="150" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">• 2 x 12 = 24  —  Çevre = 2 x (2 + 12) = 28 br</text>\n  <text x="182" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">• 3 x 8 = 24   —  Çevre = 2 x (3 + 8) = 22 br</text>\n  <text x="182" y="198" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">• 4 x 6 = 24   —  Çevre = 2 x (4 + 6) = 20 br</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f5f3ff" stroke="#7c3aed" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#6d28d9">Genelleme ve Yorum</text>\n  <text x="517" y="104" text-anchor="middle" font-size="12" fill="#4c1d95">• Alan sabitken kenarlar birbirinden</text>\n  <text x="517" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">uzaklaştıkça ÇEVRE EN BÜYÜK olur (50 br).</text>\n  <text x="517" y="158" text-anchor="middle" font-size="12" fill="#4c1d95">• Alan sabitken kenarlar birbirine</text>\n  <text x="517" y="178" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">yaklaştıkça ÇEVRE EN KÜÇÜK olur (20 br).</text>\n  <text x="517" y="214" text-anchor="middle" font-size="11" fill="#334155">Alanı aynı olan dikdörtgenlerin çevreleri farklı olabilir.</text>\n</svg>', '5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AYNI ALANA SAHİP DİKDÖRTGENLERDE ÇEVRE ANALİZİ (ALAN = 24 BR KARE)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Çarpan Çiftleriyle Kenar Bulma</text>\n  <text x="182" y="100" text-anchor="middle" font-size="12" fill="#1e3a8a">Alan = a x b = 24 birimkare ise:</text>\n  <text x="182" y="126" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">• 1 x 24 = 24  —  Çevre = 2 x (1 + 24) = 50 br</text>\n  <text x="182" y="150" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">• 2 x 12 = 24  —  Çevre = 2 x (2 + 12) = 28 br</text>\n  <text x="182" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">• 3 x 8 = 24   —  Çevre = 2 x (3 + 8) = 22 br</text>\n  <text x="182" y="198" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">• 4 x 6 = 24   —  Çevre = 2 x (4 + 6) = 20 br</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f5f3ff" stroke="#7c3aed" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#6d28d9">Genelleme ve Yorum</text>\n  <text x="517" y="104" text-anchor="middle" font-size="12" fill="#4c1d95">• Alan sabitken kenarlar birbirinden</text>\n  <text x="517" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">uzaklaştıkça ÇEVRE EN BÜYÜK olur (50 br).</text>\n  <text x="517" y="158" text-anchor="middle" font-size="12" fill="#4c1d95">• Alan sabitken kenarlar birbirine</text>\n  <text x="517" y="178" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">yaklaştıkça ÇEVRE EN KÜÇÜK olur (20 br).</text>\n  <text x="517" y="214" text-anchor="middle" font-size="11" fill="#334155">Alanı aynı olan dikdörtgenlerin çevreleri farklı olabilir.</text>\n</svg>', 'b6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÇEVRE, ALAN VE DÖRT İŞLEM BÜTÜNLEŞİK GERÇEK YAŞAM UYGULAMALARI</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Çevre İle İlgili Problemler</text>\n  <text x="182" y="100" text-anchor="middle" font-size="11.5" fill="#155e75">• Bahçe etrafına N sıra tel çekme:</text>\n  <text x="182" y="120" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0f766e">Tel Uzunluğu = (Çevre - Kapı) x Sıra Sayısı</text>\n  <text x="182" y="148" text-anchor="middle" font-size="11.5" fill="#155e75">• Çerçeve, süpürgelik, koşu parkuru</text>\n  <text x="182" y="172" text-anchor="middle" font-size="11.5" fill="#155e75">• Eş karelerin yan yana dizilmesiyle</text>\n  <text x="182" y="192" text-anchor="middle" font-size="11.5" fill="#155e75">oluşan yeni dikdörtgenin dış çevresi</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">İçte kalan ortak kenarlar çevreye katılmaz!</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Alan İle İlgili Problemler</text>\n  <text x="517" y="100" text-anchor="middle" font-size="11.5" fill="#78350f">• Oda tabanına parke / fayans döşeme:</text>\n  <text x="517" y="120" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">Maliyet = Alan (m kare) x Birim Fiyat (TL)</text>\n  <text x="517" y="148" text-anchor="middle" font-size="11.5" fill="#78350f">• Tarlaya ekilen ürün miktarı, boyama alanı</text>\n  <text x="517" y="172" text-anchor="middle" font-size="11.5" fill="#78350f">• Yürüyüş yolu çıkarıldığında kalan</text>\n  <text x="517" y="192" text-anchor="middle" font-size="11.5" fill="#78350f">yeşil bölgenin net alanı</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Büyük Alan - Küçük Alan = Kalan Alan</text>\n</svg>', '6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÇEVRE, ALAN VE DÖRT İŞLEM BÜTÜNLEŞİK GERÇEK YAŞAM UYGULAMALARI</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Çevre İle İlgili Problemler</text>\n  <text x="182" y="100" text-anchor="middle" font-size="11.5" fill="#155e75">• Bahçe etrafına N sıra tel çekme:</text>\n  <text x="182" y="120" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0f766e">Tel Uzunluğu = (Çevre - Kapı) x Sıra Sayısı</text>\n  <text x="182" y="148" text-anchor="middle" font-size="11.5" fill="#155e75">• Çerçeve, süpürgelik, koşu parkuru</text>\n  <text x="182" y="172" text-anchor="middle" font-size="11.5" fill="#155e75">• Eş karelerin yan yana dizilmesiyle</text>\n  <text x="182" y="192" text-anchor="middle" font-size="11.5" fill="#155e75">oluşan yeni dikdörtgenin dış çevresi</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">İçte kalan ortak kenarlar çevreye katılmaz!</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Alan İle İlgili Problemler</text>\n  <text x="517" y="100" text-anchor="middle" font-size="11.5" fill="#78350f">• Oda tabanına parke / fayans döşeme:</text>\n  <text x="517" y="120" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">Maliyet = Alan (m kare) x Birim Fiyat (TL)</text>\n  <text x="517" y="148" text-anchor="middle" font-size="11.5" fill="#78350f">• Tarlaya ekilen ürün miktarı, boyama alanı</text>\n  <text x="517" y="172" text-anchor="middle" font-size="11.5" fill="#78350f">• Yürüyüş yolu çıkarıldığında kalan</text>\n  <text x="517" y="192" text-anchor="middle" font-size="11.5" fill="#78350f">yeşil bölgenin net alanı</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Büyük Alan - Küçük Alan = Kalan Alan</text>\n</svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
